  2027  int
  2028  sc_asn1_sig_value_rs_to_sequence(struct sc_context *ctx, unsigned char *in, size_t inlen,
  2029                  unsigned char **buf, size_t *buflen)
  2030  {
  2031          struct sc_asn1_entry asn1_sig_value[C_ASN1_SIG_VALUE_SIZE];
  2032          struct sc_asn1_entry asn1_sig_value_coefficients[C_ASN1_SIG_VALUE_COEFFICIENTS_SIZE];
  2033          unsigned char *r = in, *s = in + inlen/2;
  2034          size_t r_len = inlen/2, s_len = inlen/2;
  2035          int rv;
  2036
  2037          LOG_FUNC_CALLED(ctx);
  2038
  2039          /* R/S are filled up with zeroes, we do not want that in sequence format */
  2040          while(r_len > 1 && *r == 0x00) {
  2041                  r++;
  2042                  r_len--;
  2043          }
  2044          while(s_len > 1 && *s == 0x00) {
  2045                  s++;
  2046                  s_len--;
  2047          }
  2048
  2049          sc_copy_asn1_entry(c_asn1_sig_value, asn1_sig_value);
  2050          sc_format_asn1_entry(asn1_sig_value + 0, asn1_sig_value_coefficients, NULL, 1);
  2051
  2052          sc_copy_asn1_entry(c_asn1_sig_value_coefficients, asn1_sig_value_coefficients);
  2053          sc_format_asn1_entry(asn1_sig_value_coefficients + 0, r, &r_len, 1);
  2054          sc_format_asn1_entry(asn1_sig_value_coefficients + 1, s, &s_len, 1);
  2055
  2056          rv = sc_asn1_encode(ctx, asn1_sig_value, buf, buflen);
  2057          LOG_TEST_RET(ctx, rv, "ASN.1 encoding ECDSA-SIg-Value failed");
  2058
  2059          LOG_FUNC_RETURN(ctx, SC_SUCCESS);
  2060  }
