  2063  int
  2064  sc_asn1_sig_value_sequence_to_rs(struct sc_context *ctx, const unsigned char *in, size_t inlen,
  2065                  unsigned char *buf, size_t buflen)
  2066  {
  2067          struct sc_asn1_entry asn1_sig_value[C_ASN1_SIG_VALUE_SIZE];
  2068          struct sc_asn1_entry asn1_sig_value_coefficients[C_ASN1_SIG_VALUE_COEFFICIENTS_SIZE];
  2069          unsigned char *r = NULL, *s = NULL;
  2070          size_t r_len = 0, s_len = 0, halflen = buflen/2;
  2071          int rv;
  2072
  2073          LOG_FUNC_CALLED(ctx);
  2074          if (!buf || !buflen)
  2075                  LOG_FUNC_RETURN(ctx, SC_ERROR_INVALID_ARGUMENTS);
  2076
  2077          sc_copy_asn1_entry(c_asn1_sig_value, asn1_sig_value);
  2078          sc_format_asn1_entry(asn1_sig_value + 0, asn1_sig_value_coefficients, NULL, 0);
  2079
  2080          sc_copy_asn1_entry(c_asn1_sig_value_coefficients, asn1_sig_value_coefficients);
  2081          sc_format_asn1_entry(asn1_sig_value_coefficients + 0, &r, &r_len, 0);
  2082          sc_format_asn1_entry(asn1_sig_value_coefficients + 1, &s, &s_len, 0);
  2083
  2084          rv = sc_asn1_decode(ctx, asn1_sig_value, in, inlen, NULL, NULL);
  2085          LOG_TEST_GOTO_ERR(ctx, rv, "ASN.1 decoding ECDSA-Sig-Value failed");
  2086
  2087          if (halflen < r_len || halflen < s_len)   {
  2088                  rv = SC_ERROR_BUFFER_TOO_SMALL;
  2089                  goto err;
  2090          }
  2091
  2092          memset(buf, 0, buflen);
  2093          memcpy(buf + (halflen - r_len), r, r_len);
  2094          memcpy(buf + (buflen - s_len), s, s_len);
  2095
  2096          sc_log(ctx, "r(%"SC_FORMAT_LEN_SIZE_T"u): %s", halflen,
  2097                 sc_dump_hex(buf, halflen));
  2098          sc_log(ctx, "s(%"SC_FORMAT_LEN_SIZE_T"u): %s", halflen,
  2099                 sc_dump_hex(buf + halflen, halflen));
  2100
  2101          rv = SC_SUCCESS;
  2102  err:
  2103          free(r);
  2104          free(s);
  2105
  2106          LOG_FUNC_RETURN(ctx, rv);
  2107  }
