   797  int
   798  sc_asn1_decode_object_id(const u8 *inbuf, size_t inlen, struct sc_object_id *id)
   799  {
   800          int a;
   801          const u8 *p = inbuf;
   802          int *octet;
   803
   804          if (inlen == 0 || inbuf == NULL || id == NULL)
   805                  return SC_ERROR_INVALID_ARGUMENTS;
   806
   807          sc_init_oid(id);
   808          octet = id->value;
   809
   810          a = *p;
   811          *octet++ = a / 40;
   812          *octet++ = a % 40;
   813          inlen--;
   814
   815          while (inlen) {
   816                  p++;
   817                  a = *p & 0x7F;
   818                  inlen--;
   819                  while (inlen && *p & 0x80) {
   820                          /* Limit the OID values to int size and do not overflow */
   821                          if (a > (INT_MAX>>7)) {
   822                                  sc_init_oid(id);
   823                                  return SC_ERROR_NOT_SUPPORTED;
   824                          }
   825                          p++;
   826                          a <<= 7;
   827                          a |= *p & 0x7F;
   828                          inlen--;
   829                  }
   830                  *octet++ = a;
   831                  if (octet - id->value >= SC_MAX_OBJECT_ID_OCTETS)   {
   832                          sc_init_oid(id);
   833                          return SC_ERROR_INVALID_ASN1_OBJECT;
   834                  }
   835          };
   836
   837          return 0;
   838  }
